        'rh.sec.you':           'நீங்கள்',
        'lbl.rh.age':           'தற்போதைய வயது',
        'lbl.rh.retage':        'ஓய்வு வயது',
        'lbl.rh.livetill':      'வாழும் வரை (வயது)',
        'rh.hint.conservative': 'பாதுகாப்பான திட்டமிடலுக்கு 95 பயன்படுத்துங்கள்',
        'lbl.rh.inflation':     'பணவீக்கம் % ஆண்டுக்கு',
